import{_ as i,o as a,c as e,a2 as t}from"./chunks/framework.hwbV7reR.js";const c=JSON.parse('{"title":"Нагрузка и сроки выполнения","description":"","frontmatter":{},"headers":[],"relativePath":"runtime-limits.md","filePath":"runtime-limits.md","lastUpdated":1791695486000}'),n={name:"runtime-limits.md"};function l(p,s,h,r,o,k){return a(),e("div",null,[...s[0]||(s[0]=[t(`<h1 id="нагрузка-и-сроки-выполнения" tabindex="-1">Нагрузка и сроки выполнения <a class="header-anchor" href="#нагрузка-и-сроки-выполнения" aria-label="Permalink to &quot;Нагрузка и сроки выполнения&quot;">​</a></h1><p>Оркестратор переиспользует HTTP-соединения с агентами. На процесс создаётся один HTTPX AsyncClient и отдельный цикл asyncio; синхронный драйвер ждёт результат. Работа с SQLite и блокировки назначений остаются в вызывающем потоке. Это позволяет прерывать сетевое ожидание по общему сроку, включая ответ, который приходит маленькими частями, без оставленного фонового потока мутации. Используются <a href="https://www.python-httpx.org/async/" target="_blank" rel="noreferrer">жизненный цикл HTTPX</a> и <a href="https://docs.python.org/3.12/library/asyncio-task.html#asyncio.timeout" target="_blank" rel="noreferrer">отмена по сроку asyncio</a>.</p><h2 id="настроики" tabindex="-1">Настройки <a class="header-anchor" href="#настроики" aria-label="Permalink to &quot;Настройки&quot;">​</a></h2><p>Поля находятся в <code>policy.agents</code> файла settings.json; <a href="./configuration.html">границы значений</a>.</p><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;policy&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">    &quot;agents&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: {</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;operation_timeout_seconds&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">30</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;queue_timeout_seconds&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">2</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;max_concurrent_requests&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">16</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;max_concurrent_per_node&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">4</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;max_pending_requests&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">64</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;max_pending_per_node&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">8</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;connect_timeout_seconds&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">4</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">      &quot;response_timeout_seconds&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">12</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><ul><li>До 16 исходящих HTTP-запросов одновременно, до 4 на один узел.</li><li>До 64 принятых обращений к транспорту, включая выполняющиеся и ожидающие. До 8 обращений на узел: один занятый сервер не может заполнить всю очередь. При заполнении любого pending-лимита новое обращение отклоняется сразу.</li><li>Ожидание допуска — до 2 секунд. Сначала берётся место узла, затем общее: очередь занятого узла не резервирует глобальные места.</li><li>Один HTTP-запрос ограничен 12 секундами целиком, а установление соединения — 4. Ранее response_timeout ограничивал отдельное ожидание чтения; теперь медленная непрерывная передача тоже ограничена. Пределы размеров ответа сохранены.</li><li>Прикладная операция имеет общий бюджет 30 секунд. Проверка идентичности, наблюдения серверов, чтение параметров и мутации используют остаток этого бюджета. Вложенный вызов не начинает отсчёт заново.</li></ul><p>Лимиты относятся к одному экземпляру runtime. API, recovery и lease-worker имеют собственные пулы; пользовательская очередь API не занимает места heartbeat. Это не общая квота между процессами или машинами. Перезапуск применяет настройки; увеличение числа процессов умножает суммарную нагрузку на агенты. <code>selection.observation_workers</code> по-прежнему ограничивает параллельный обход в одном запросе; исходящие обращения всех обходов дополнительно проходят общий ограничитель.</p><h2 id="что-ограничивает-общии-срок" tabindex="-1">Что ограничивает общий срок <a class="header-anchor" href="#что-ограничивает-общии-срок" aria-label="Permalink to &quot;Что ограничивает общий срок&quot;">​</a></h2><p>Отсчёт начинается при входе в прикладной сценарий. Он не включает загрузку тела входящего HTTP-запроса или ожидание потока FastAPI. Ожидания HTTP и допуска отменяются по сроку; межпроцессная блокировка и ожидание SQLite используют остаток времени. Новая выдача после истечения бюджета не запускается. В recovery бюджет задаётся на одно назначение, в heartbeat — на один узел, а не на весь проход.</p><p>Бюджет не является жёстким пределом доставки HTTP-ответа: фиксация уже полученного результата, rollback/закрытие ресурсов, работа диска и синхронная запись логов не прерываются насильно. После подтверждённой мутации нужно сохранить её результат, даже если сеть заняла весь отведённый срок. Ограничения reverse proxy и systemd должны учитывать это завершение, а не убивать процесс ровно на 30-й секунде.</p><h2 id="повторы-и-отказ-узла" tabindex="-1">Повторы и отказ узла <a class="header-anchor" href="#повторы-и-отказ-узла" aria-label="Permalink to &quot;Повторы и отказ узла&quot;">​</a></h2><p>Автоматических транспортных повторов нет, включая POST. Отмена запроса на нашей стороне не отменяет действие у агента. Назначение и ключ сохраняются до отправки; повтор создаёт/находит тот же peer на закреплённом узле. Незавершённое переключение продолжает журналируемую операцию с подтверждённым отзывом старого доступа.</p><p>Переполненная локальная очередь возвращает прежний <code>503 connection_busy</code>, общий срок — <code>503 node_unavailable</code>. Внутри сервиса это отдельные типы ошибок: recovery и switch не принимают их за отказ исходного сервера и не закрывают его разрешение. Доверенный backend повторяет исходный запрос с задержкой и ограничением попыток; новый device_id или новый ключ для обхода ошибки использовать нельзя.</p><p>Диагностика добавляет <code>agent_queue</code> для времени допуска и причины <code>saturated</code> и <code>deadline</code>. Эти данные помогают отличить перегрузку оркестратора от ответа агента. Ни один из этих сигналов сам по себе не доказывает сбой пользовательского туннеля.</p><h2 id="жизненныи-цикл-и-проверки" tabindex="-1">Жизненный цикл и проверки <a class="header-anchor" href="#жизненныи-цикл-и-проверки" aria-label="Permalink to &quot;Жизненный цикл и проверки&quot;">​</a></h2><p>HTTP-пул закрывается при завершении API, CLI и worker. Ключ передаётся только заголовком конкретного запроса; cookies агентов не сохраняются. Проверки TLS, server identity, запрет перенаправлений и игнорирование proxy-переменных сохранены. Пул не содержит кэша конфигураций и не записывает секретные ответы на диск.</p><p><code>tests/test_runtime_limits.py</code> проверяет общую и узловую параллельность, переполнение, отмену очереди и медленного потока, восстановление после потери ответа создания, отсутствие ложного переноса и закрытие runtime. Тест с временным HTTP-сервером на loopback проверяет настоящее переиспользование TCP и изоляцию заголовков; для него нужны разрешённые локальные сокеты. Конфигурация рабочих узлов по-прежнему требует HTTPS.</p>`,17)])])}const E=i(n,[["render",l]]);export{c as __pageData,E as default};
